const D = { n: 28, scale: 1, energy: .6, hue: 28, speed: 1, density: .5, spread: .6, x: .5, y: .82, seed: 0, style: 'backlit', pal: 'sunset', act: 'crowd' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (x,a,b) => x < a ? a : x > b ? b : x;
const c01 = x => x < 0 ? 0 : x > 1 ? 1 : x;
const TAU = 6.28318530718;
const W = width, H = height, u = Math.min(W, H);

let bt = K.beat * P.speed;
if (S.lastBeat == null || bt < S.lastBeat) S.lastBeat = bt;
S.lastBeat = bt;

// smoothed audio
S.bass = (S.bass || 0) * .82 + (A.bass || 0) * .18;
S.tre  = (S.tre  || 0) * .78 + (A.treble || 0) * .22;
S.rms  = (S.rms  || 0) * .85 + (A.rms || 0) * .15;

const eAmp = .35 + .65 * P.energy;
const kick = c01(K.pulse * (.55 + .45 * K.intensity) + S.bass * .85);
const swell = K.swell;                                   // smooth breathe 0..1
// hands-up level rises with musical intensity + surges on odd sections (chorus feel)
const surge = (K.section % 2) ? .35 : 0;
const handsBase = c01(.12 + .72 * K.intensity + surge);

// ---- act dramaturgy (multi-minute) ----
const ACTS = {
  crowd:  { waveAmp: .55, wavePace: .5,  hop: 1,   phones: 1 },   // full festival wave
  ambient:{ waveAmp: .22, wavePace: .28, hop: .55, phones: .5 },  // swaying, arms mostly down
  frenzy: { waveAmp: .7,  wavePace: .82, hop: 1.35,phones: 1.3 }  // moshing, everyone up
};
const act = ACTS[P.act] || ACTS.crowd;

const style = P.style;
const paper = style === 'riso';

// ---- palette ----
const PALS = {
  sunset:  { glow: [P.hue, 78, 96], sky: [(P.hue + 285) % 360, 55, 8], ink: (P.hue + 10) % 360, phone: 44 },
  laser:   { glow: [312, 88, 92],   sky: [268, 70, 7],  ink: 300, phone: 190 },
  gold:    { glow: [46, 82, 100],   sky: [30, 45, 6],   ink: 40,  phone: 52 },
  cold:    { glow: [205, 72, 90],   sky: [230, 62, 8],  ink: 210, phone: 190 },
  mono:    { glow: [0, 0, 88],      sky: [0, 0, 5],     ink: 0,   phone: 0 }
};
const PL = PALS[P.pal] || PALS.sunset;

// ---- roster build (seed/count dependent) ----
const N = Math.max(4, Math.round(P.n));
const rosterKey = N + '|' + P.seed + '|' + P.spread;
if (S.rosterKey !== rosterKey) {
  S.rosterKey = rosterKey;
  const R = Math.min(6, Math.max(2, Math.round(Math.sqrt(N) * .78)));
  S.R = R;
  const fx = [], row = [], ph = [], szj = [], hasP = [], pph = [], ord = [];
  for (let i = 0; i < N; i++) {
    // front-biased row assignment (more bodies near camera)
    const r = Math.floor(R * Math.pow(fr(i * 2.3 + 7), .72));
    row.push(Math.min(R - 1, r));
    const sprd = .5 + .5 * P.spread;
    fx.push(.5 + (fr(i * 1.7 + 3) - .5) * sprd);
    ph.push(fr(i * 3.1 + 11));
    szj.push(.82 + fr(i * 5.9 + 2) * .4);
    hasP.push(fr(i * 9.3 + 5) < .34);
    pph.push(fr(i * 4.4 + 8));
    ord.push(i);
  }
  // paint back-to-front
  ord.sort((a, b) => row[a] - row[b]);
  S.fx = fx; S.row = row; S.ph = ph; S.szj = szj; S.hasP = hasP; S.pph = pph; S.ord = ord;
}
const R = S.R;

// ---- backdrop cache ----
const bdKey = W + 'x' + H + '|' + style + '|' + P.pal + '|' + P.seed + '|' + Math.round(P.hue);
if (!S.bd || S.bdKey !== bdKey) {
  S.bdKey = bdKey;
  const g = createGraphics(W, H);
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke();
  const hy = H * 0.6;
  const step = Math.max(2, Math.round(H / 140));
  if (paper) {
    // riso paper: warm cream ground + faint grain
    g.background(38, 12, 93, 100);
    for (let k = 0; k < 1400; k++) {
      const gx = fr(k * 1.1 + 1) * W, gy = fr(k * 2.7 + 3) * H;
      g.fill(38, 16, 70, 5 + fr(k) * 8);
      g.rect(gx, gy, 2, 2);
    }
  } else if (style === 'backlit') {
    // dark sky with a hot horizon glow band + stage light shafts
    for (let yy = 0; yy < H; yy += step) {
      const d = Math.abs(yy - hy) / H;
      const glow = Math.exp(-d * d * 20);
      const bri = PL.sky[2] + (PL.glow[2] - PL.sky[2]) * glow * (yy < hy ? 1 : .55);
      const sat = PL.sky[1] + (PL.glow[1] - PL.sky[1]) * glow;
      const hu = PL.sky[0] + (((PL.glow[0] - PL.sky[0] + 540) % 360) - 180) * glow;
      g.fill((hu + 360) % 360, sat, bri, 100);
      g.rect(0, yy, W, step + 1);
    }
    // light shafts from above
    g.blendMode(g.ADD);
    const shafts = 3 + Math.floor(fr(90) * 3);
    for (let sI = 0; sI < shafts; sI++) {
      const sx = (fr(sI * 7 + 4) * .8 + .1) * W;
      const sw = u * (.12 + fr(sI * 3 + 1) * .18);
      g.noStroke();
      for (let b = 0; b < 5; b++) {
        g.fill(PL.glow[0], PL.glow[1] * .7, PL.glow[2], 5 - b);
        g.triangle(sx, -H * .05, sx - sw * (1 + b * .4), hy, sx + sw * (1 + b * .4), hy);
      }
    }
    g.blendMode(g.BLEND);
  } else {
    // thermal / wire: deep dark gradient, cool
    const base = style === 'thermal' ? [232, 70, 6] : [220, 55, 5];
    for (let yy = 0; yy < H; yy += step) {
      const t = yy / H;
      g.fill(base[0], base[1], base[2] + t * 5 + (1 - Math.abs(t - .58) * 1.6) * 3, 100);
      g.rect(0, yy, W, step + 1);
    }
  }
  S.bd = g;

  // halftone overlay for riso (sparse dot texture)
  if (paper) {
    const ht = createGraphics(W, H);
    ht.colorMode(ht.HSB, 360, 100, 100, 100);
    ht.noStroke();
    const cell = Math.max(6, Math.round(u * .016));
    for (let yy = 0; yy < H; yy += cell) for (let xx = 0; xx < W; xx += cell) {
      ht.fill(0, 0, 0, 6);
      ht.ellipse(xx, yy, cell * .38, cell * .38);
    }
    S.ht = ht;
  } else S.ht = null;
}
image(S.bd, 0, 0, W, H);

// ---- geometry / draw ----
const hy = H * 0.6;
const baseSz = u * 0.16 * P.scale;
const feetTop = P.y * H;                                  // front row feet line
const bandH = H * 0.30;

function figure(i) {
  const r = S.row[i];
  const dep = R > 1 ? r / (R - 1) : 1;                    // 0 back .. 1 front
  const sz = baseSz * (0.52 + 0.62 * dep) * S.szj[i];
  const px = S.fx[i] * W;
  const py = (feetTop - bandH) + bandH * dep + (fr(i * 6 + 1) - .5) * sz * .12;
  const phi = S.ph[i];

  // per-figure jump (staggered slightly by depth so a ripple reads)
  const jk = c01(kick - dep * .06 * (1 - kick));
  const jump = jk * sz * 0.26 * (0.55 + 0.9 * eAmp) * act.hop;
  const sway = Math.sin(bt * 0.5 + phi * TAU) * sz * 0.06 * (0.5 + eAmp);
  const breath = swell * sz * 0.04;

  // arm wave: travels across x, plus base hands-up
  const wave = act.waveAmp * Math.sin(S.fx[i] * 1.6 * TAU - bt * act.wavePace * TAU);
  const raise = c01(handsBase * (.4 + .6 * eAmp) + (0.4 + 0.6 * eAmp) * (wave * .5 + .18) + S.bass * .25);

  const cx = px + sway;
  const cy = py - jump - breath;

  // depth ink
  let bri = 22 - 19 * dep, alph = 68 + 28 * dep;
  const hazeUp = dep < .5 ? (1 - dep * 2) * 6 : 0;        // atmospheric lift for back rows

  push();
  translate(cx, cy);

  if (style === 'wire') {
    // X-ray skeletal figure — glowing thin strokes, no fill (glow via double-stroke, no shadowBlur)
    noFill(); strokeCap(ROUND);
    const ax = sz * .22, ay = -sz * .64;
    const hx = ax + raise * sz * .16, hyw = ay - raise * sz * .95;
    const bones = () => {
      ellipse(0, -sz * .9, sz * .30, sz * .34);            // skull
      line(0, -sz * .72, 0, -sz * .05);                    // spine
      for (let rb = 0; rb < 3; rb++) { const yy = -sz * (.6 - rb * .16); line(-sz * (.16 - rb * .02), yy, sz * (.16 - rb * .02), yy); }
      line(-ax, ay, -hx, hyw); line(ax, ay, hx, hyw);      // arms
      line(0, -sz * .05, -sz * .18, sz * .42); line(0, -sz * .05, sz * .18, sz * .42); // legs
    };
    stroke(PL.ink, PL.glow[1] * .5, 90, 22 + 18 * dep); strokeWeight(Math.max(2, sz * .14)); bones(); // soft glow pass
    stroke(PL.ink, PL.glow[1] * .35, 100, 78 + 20 * jk); strokeWeight(Math.max(1, sz * .045)); bones(); // bright pass
    pop();
    return;
  }

  if (style === 'thermal') {
    // false-color heat: cool outer + hot core (layered additive, no shadowBlur)
    const heat = c01(.35 + .5 * jk + .25 * raise + .2 * S.rms);
    const cool = cl(232 - heat * 44, 150, 232), hot = cl(60 - heat * 55, 2, 60);
    noStroke(); blendMode(ADD);
    fill(cool, 80, 24 + heat * 22, 22); ellipse(0, -sz * .52, sz * 1.05, sz * 1.72);   // cool halo
    fill(cl(cool - 20, 30, 232), 82, 34 + heat * 26, 26); ellipse(0, -sz * .58, sz * .66, sz * 1.06);
    fill(hot, 90, 62 + heat * 38, 55); ellipse(0, -sz * .9, sz * .34, sz * .38);        // hot head
    beginShape();
    vertex(-sz * .26, 0); vertex(-sz * .3, -sz * .62); vertex(sz * .3, -sz * .62); vertex(sz * .26, 0);
    endShape(CLOSE);
    fill(cl(hot + 8, 5, 62), 70, 90, 60); ellipse(0, -sz * .9, sz * .18, sz * .2);      // white-hot core
    strokeWeight(sz * .14); strokeCap(ROUND); stroke(hot, 92, 72 + heat * 28, 60); noFill();
    const ax = sz * .24, ay = -sz * .62, hx = ax + raise * sz * .16, hyt = ay - raise * sz * .95;
    line(-ax, ay, -hx, hyt); line(ax, ay, hx, hyt);
    blendMode(BLEND);
    pop();
    return;
  }

  // ---- backlit (default) & riso silhouette body ----
  const drawBody = (hueI, sI, bI, aI, sw) => {
    noStroke();
    fill(hueI, sI, bI, aI);
    // head
    ellipse(0, -sz * .9, sz * .32, sz * .36);
    // torso silhouette
    beginShape();
    vertex(-sz * .27, sz * .02);
    vertex(-sz * .30, -sz * .58);
    vertex(-sz * .18, -sz * .70);
    vertex(sz * .18, -sz * .70);
    vertex(sz * .30, -sz * .58);
    vertex(sz * .27, sz * .02);
    endShape(CLOSE);
    // arms (thick strokes)
    stroke(hueI, sI, bI, aI); strokeWeight(sw); strokeCap(ROUND); noFill();
    const ax = sz * .24, ay = -sz * .62;
    const hx = ax + raise * sz * .18, hyy = ay - raise * sz * .96;
    // elbow bend
    const ex = ax + raise * sz * .05, ey = ay - raise * sz * .5;
    line(-ax, ay, -ex, ey); line(-ex, ey, -hx, hyy);
    line(ax, ay, ex, ey); line(ex, ey, hx, hyy);
    noStroke();
  };

  if (paper) {
    // riso: two ink layers, misregistered
    const off = sz * .05;
    push(); translate(-off, off * .6);
    drawBody((PL.ink + 175) % 360, 70, 62, 46, sz * .12);   // ink 2 (offset)
    pop();
    drawBody(PL.ink, 74, 40, 52, sz * .12);                 // ink 1
  } else {
    // backlit silhouette
    drawBody((PL.ink + 6) % 360, 34, cl(bri + hazeUp, 2, 34), alph, sz * .13);
    // rim light on the glow side (front rows only)
    if (dep > .45) {
      stroke(PL.glow[0], PL.glow[1] * .7, PL.glow[2], 40 * dep);
      strokeWeight(Math.max(1, sz * .04)); noFill();
      arc(0, -sz * .9, sz * .32, sz * .36, -TAU * .32, TAU * .12);
      noStroke();
    }
  }

  // phone light held up (twinkles)
  if (S.hasP[i] && raise > .45 && !paper) {
    const tw = .45 + .55 * Math.sin(bt * 3.3 + S.pph[i] * TAU) + S.tre * 1.2;
    if (tw > .2) {
      blendMode(ADD);
      const px2 = (S.fx[i] > .5 ? 1 : -1) * (sz * .24 + raise * sz * .18);
      const py2 = -sz * .62 - raise * sz * .96;
      noStroke();
      fill(PL.phone, P.pal === 'mono' ? 0 : 30, 100, cl(30 + 40 * tw, 0, 80));
      ellipse(px2, py2, sz * .16 * (1 + .3 * tw), sz * .16 * (1 + .3 * tw));
      fill(PL.phone, 10, 100, cl(50 + 50 * tw, 0, 95));
      ellipse(px2, py2, sz * .07, sz * .07);
      blendMode(BLEND);
    }
  }
  pop();
}

for (let k = 0; k < S.ord.length; k++) figure(S.ord[k]);

// ---- extra float phone-lights / spark motes (density) among far crowd ----
if (P.density > 0.02 && style !== 'wire') {
  const m = Math.round(P.density * 26 * act.phones);
  noStroke(); blendMode(ADD);
  for (let i = 0; i < m; i++) {
    const fx = (fr(i * 2.1 + 30) * .9 + .05) * W;
    const fy = hy + fr(i * 3.7 + 40) * (bandH * .8);
    const tw = .4 + .6 * Math.sin(bt * 2.2 + fr(i + 60) * TAU) + S.tre * 1.4;
    if (tw < .15) continue;
    fill(paper ? PL.ink : PL.phone, paper ? 60 : 24, 100, cl(14 + 26 * tw, 0, 55));
    const d = u * .012 * (1 + .5 * tw);
    ellipse(fx, fy, d, d);
  }
  blendMode(BLEND);
}

// halftone overlay (riso only)
if (paper && S.ht) { blendMode(MULTIPLY); image(S.ht, 0, 0, W, H); blendMode(BLEND); }

blendMode(BLEND);
